/**
 * Session cache. Plain object by the final decision: it must serialize.
 */
export function createCache() {
  let store = Object.create(null)
  return {
    set(key, value) { store[key] = value },
    get(key) { return store[key] },
    snapshot() { return { ...store } },
  }
}

